-- ============================================================================
-- dbdlp openDLP 来源测试集（Oracle 版）
-- ----------------------------------------------------------------------------
-- 数据来源 : hitsz-ids/openDLP 测试数据集（Apache-2.0）
--            https://github.com/hitsz-ids/openDLP  tests/data/
-- 本地源   : C:\Users\biu\AppData\Local\Temp\dlp_datasets
-- 转换工具 : testdata/tools/opendlp_to_sql.py（变更源数据后可全量再生）
-- 规模     : 长表每类 500 对正负样本（14 类共 14000 行）；
--            宽表取综合基准表前 1000 行（17 列全类型）
-- 类型映射 : TELEPHONE→FIXED_PHONE；LICENSE_PLATE→PLATE；DOMAIN_NAME→DOMAIN（预留）；
--            IPV6/MAC/DATE 为 dbdlp 规则预留数据，未实现前不应误判
-- 用法     : 长表配合程序化断言统计召回/误报；宽表直接用 dbdlp 扫描出报告基准
-- ============================================================================

-- ============================================================================
-- 0. 清理旧表
-- ============================================================================
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE T_DBDLP_TEST_OPENDLP_PAIRS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE T_DBDLP_TEST_OPENDLP_WIDE CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

-- ============================================================================
-- 1. 长表：逐条正负样本断言（按类轮转交错排列，前28行即覆盖全部14类正负样本）
-- ============================================================================
CREATE TABLE T_DBDLP_TEST_OPENDLP_PAIRS (
  PAIR_ID      NUMBER        PRIMARY KEY,
  SAMPLE_TYPE  VARCHAR2(32),
  IS_POSITIVE  NUMBER(1),
  SAMPLE_VALUE VARCHAR2(128)
);

COMMENT ON TABLE  T_DBDLP_TEST_OPENDLP_PAIRS IS 'openDLP来源-逐条样本断言表';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_PAIRS.SAMPLE_TYPE  IS '样本类型编号';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_PAIRS.IS_POSITIVE  IS '是否正样本';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_PAIRS.SAMPLE_VALUE IS '样本值';

-- ============================================================================
-- 2. 宽表：字段级扫描基准（17 列全类型综合数据）
-- ============================================================================
CREATE TABLE T_DBDLP_TEST_OPENDLP_WIDE (
  WIDE_ID NUMBER PRIMARY KEY,
  PERSON VARCHAR2(128),
  ID_CARD VARCHAR2(128),
  TELEPHONE VARCHAR2(128),
  MOBILE_PHONE VARCHAR2(128),
  EMAIL VARCHAR2(128),
  LICENSE_PLATE VARCHAR2(128),
  BANK_CARD VARCHAR2(128),
  PASSPORT VARCHAR2(128),
  COMPANY_NAME VARCHAR2(128),
  SOCIAL_CREDIT_CODE VARCHAR2(128),
  IPV4 VARCHAR2(128),
  IPV6 VARCHAR2(128),
  MAC VARCHAR2(128),
  DOMAIN_NAME VARCHAR2(128),
  LOCATION VARCHAR2(128),
  POSTCODE VARCHAR2(128),
  SAMPLE_DATE VARCHAR2(128)
);

COMMENT ON TABLE T_DBDLP_TEST_OPENDLP_WIDE IS 'openDLP来源-字段级扫描基准表';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.PERSON IS '姓名';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.ID_CARD IS '身份证号码';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.TELEPHONE IS '固定电话';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.MOBILE_PHONE IS '手机号';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.EMAIL IS '电子邮箱';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.LICENSE_PLATE IS '车牌号码';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.BANK_CARD IS '银行卡号';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.PASSPORT IS '护照号码';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.COMPANY_NAME IS '公司名称';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.SOCIAL_CREDIT_CODE IS '统一社会信用代码';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.IPV4 IS 'IPv4地址';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.IPV6 IS 'IPv6地址';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.MAC IS 'MAC地址';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.DOMAIN_NAME IS '域名';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.LOCATION IS '地址';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.POSTCODE IS '邮政编码';
COMMENT ON COLUMN T_DBDLP_TEST_OPENDLP_WIDE.SAMPLE_DATE IS '日期';

